#include<bits/stdc++.h>

using namespace std;

int n,k;
int r[8];
int seq[8];

void solve(int lv){
  if(lv==n){
    int s=0;
    for(int i=0;i<n;i++){ s+=seq[i]; }
    if(s%k==0){
      for(int i=0;i<n;i++){
        if(i){cout << " ";}
        cout << seq[i];
      }cout << "\n";
    }
    return;
  }
  for(int i=1;i<=r[lv];i++){
    seq[lv]=i;
    solve(lv+1);
  }
}

int main(){
  cin >> n >> k;
  for(int i=0;i<n;i++){
    cin >> r[i];
  }
  solve(0);
  return 0;
}

#include<bits/stdc++.h>

using namespace std;

int n,k;
int r[8];
int seq[8];

int main(){
  cin >> n >> k;
  int tot=1;
  for(int i=0;i<n;i++){
    cin >> r[i];
    tot*=r[i];
  }
  for(int t=0;t<tot;t++){
    int x=t;
    int s=0;
    for(int i=n-1;i>=0;i--){
      seq[i]=(x%r[i])+1;
      s+=seq[i];
      x/=r[i];
    }
    if(s%k==0){
      for(int i=0;i<n;i++){
        if(i){cout << " ";}
        cout << seq[i];
      }cout << "\n";
    }
  }
  return 0;
}

